#include "can_v_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void q_init (Q_Node * q_root)
{
  q_root->lhs = q_root->rhs = q_root ;
}

//--------------------------------------------------------------------------//

void q_unlink (Q_Node * q_node)
{
  q_node->lhs->rhs = q_node->rhs ;
  q_node->rhs->lhs = q_node->lhs ;
}

//--------------------------------------------------------------------------//

void q_link_rhs (Q_Node * q_root , Q_Node * q_node)
{
  q_node->lhs      = q_root      ;
  q_node->rhs      = q_root->rhs ;
  q_node->rhs->lhs = q_node      ;
  q_root->rhs      = q_node      ;
}

//--------------------------------------------------------------------------//

void q_link_lhs (Q_Node * q_root , Q_Node * q_node)
{
  q_node->rhs      = q_root      ;
  q_node->lhs      = q_root->lhs ;
  q_node->lhs->rhs = q_node      ;
  q_root->lhs      = q_node      ;
}

